# November 19, 2026: Annapolis County, Nova Scotia: Annapolis Royal and the Annapolis Basin shore (Port Royal, Granville
# Ferry, Upper Clements, Clementsport, Victoria Beach), Lequille, and the valley east to Bridgetown, Tupperville, Hampton,
# Mount Hanley and Middleton. Region ns drawn at random by tools/choose.py --claim --state ns. Sources opened in this
# session: the Canadian Register of Historic Places statement for each place (historicplaces.ca, read with tools/page.py
# --all); Parks Canada's visit and hours pages for Fort Anne, Port-Royal and the Melanson Settlement; the Annapolis
# Heritage Society's pages for its three museums; the Old Holy Trinity Charitable Trust's site and the Town of Middleton's
# page on the church; the James House Museum's site; Lighthousefriends.com for the three lighthouses (positions, parking
# and owners); Wikipedia's list of historic places in Annapolis County (Register ids and coordinates).
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def HP(t,i): return ['Canadian Register of Historic Places: '+t,'https://www.historicplaces.ca/en/rep-reg/place-lieu.aspx?id=%d'%i]
